from solution import square_Sum


def test_issue_example_n2():
    """Example: square_Sum(2) == 20."""
    assert square_Sum(2) == 20  # 2^2 + 4^2 = 4 + 16 = 20


def test_issue_n1_single_even():
    """Sum of squares of first 1 even natural number is 4."""
    assert square_Sum(1) == 4  # 2^2 = 4


def test_issue_n3_three_evens():
    """Sum of squares of first 3 even natural numbers is 56."""
    assert square_Sum(3) == 56  # 4 + 16 + 36 = 56


def test_issue_n4_four_evens():
    """Sum of squares of first 4 even natural numbers is 120."""
    assert square_Sum(4) == 120  # 4 + 16 + 36 + 64 = 120


def test_issue_n5_five_evens():
    """Sum of squares of first 5 even natural numbers is 220."""
    assert square_Sum(5) == 220  # 120 + 10^2 = 120 + 100 = 220


def test_issue_n0_empty_sum():
    """Sum of squares of first 0 even natural numbers is 0."""
    assert square_Sum(0) == 0  # empty sum = 0


def test_issue_n10_ten_evens():
    """Sum of squares of first 10 even natural numbers is 1540."""
    assert square_Sum(10) == 1540  # 4+16+36+64+100+144+196+256+324+400 = 1540


def test_contract_evens_not_odds():
    """Contract: must sum squares of evens, not odds."""
    assert square_Sum(6) == 364  # 220 + 12^2 = 220 + 144 = 364


def test_contract_sum_of_squares():
    """Contract: must return sum of squares, not square of sum."""
    assert square_Sum(7) == 560  # 364 + 14^2 = 364 + 196 = 560


def test_contract_starts_at_two():
    """Contract: first even natural is 2, so accumulation starts at 4."""
    assert square_Sum(8) == 816  # 560 + 16^2 = 560 + 256 = 816
